#!/usr/bin/env bash
# =============================================================================
# example_script.sh
# Aplica el icono circular azul (sin fondo blanco) al proyecto Control TV.
#
# Uso en GitHub Codespaces / workspace:
#   git pull
#   bash example_script.sh
#
# Ejecutar desde la raíz del repo (donde está settings.gradle.kts y app/).
# Es seguro repetirlo.
# =============================================================================
set -euo pipefail

log()  { printf '→ %s\n' "$*"; }
ok()   { printf '✓ %s\n' "$*"; }
die()  { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

find_root() {
  local dir="$PWD"
  local cand
  for cand in "$dir" "$dir/RemoteControlTV-main" "$dir/TVRemote"; do
    if [[ -f "$cand/settings.gradle.kts" || -f "$cand/settings.gradle" ]] \
       && [[ -d "$cand/app/src/main/res" ]]; then
      (cd "$cand" && pwd)
      return 0
    fi
  done
  local p="$dir"
  while [[ "$p" != "/" ]]; do
    if [[ -d "$p/app/src/main/res" && ( -f "$p/settings.gradle.kts" || -f "$p/settings.gradle" ) ]]; then
      echo "$p"
      return 0
    fi
    p="$(dirname "$p")"
  done
  return 1
}

ROOT="$(find_root)" || die "No encuentro el proyecto Android (settings.gradle.kts + app/src/main/res).
Ejecuta el script desde la raíz del repo después de 'git pull'."
cd "$ROOT"
log "Proyecto: $ROOT"

RES="app/src/main/res"
MANIFEST="app/src/main/AndroidManifest.xml"
[[ -d "$RES" ]] || die "No existe $RES"
[[ -f "$MANIFEST" ]] || die "No existe $MANIFEST"

STAMP="$(date +%Y%m%d_%H%M%S)"
BAK=".icon-backup-$STAMP"
mkdir -p "$BAK"
find "$RES" -type f -name 'ic_launcher*' -exec cp --parents {} "$BAK/" \; || true
if find "$BAK" -type f -print -quit | grep -q .; then
  ok "Backup de iconos anteriores en $BAK"
else
  rmdir "$BAK" 2>/dev/null || true
fi



PAYLOAD_DIR="$(mktemp -d)"
trap 'rm -rf "$PAYLOAD_DIR"' EXIT

log "Extrayendo iconos..."
SELF="${BASH_SOURCE[0]:-$0}"
[[ -f "$SELF" ]] || SELF="$0"
awk 'BEGIN{p=0} /^__ICON_PAYLOAD_B64__$/{p=1; next} /^__ICON_PAYLOAD_END__$/{p=0} p' "$SELF" \
  | tr -d '\n\r ' \
  | base64 -d \
  > "$PAYLOAD_DIR/payload.tar.gz"
tar -tzf "$PAYLOAD_DIR/payload.tar.gz" >/dev/null \
  || die "No pude decodificar el payload del icono (¿archivo truncado?)."
tar -xzf "$PAYLOAD_DIR/payload.tar.gz" -C "$PAYLOAD_DIR"
[[ -d "$PAYLOAD_DIR/res" ]] || die "Payload incompleto."

log "Escribiendo mipmaps, drawable y icono adaptativo..."
cp -a "$PAYLOAD_DIR/res/." "$RES/"

if [[ -f "$RES/drawable/ic_launcher_foreground.xml" ]]; then
  rm -f "$RES/drawable/ic_launcher_foreground.xml"
  ok "Eliminado drawable/ic_launcher_foreground.xml (sustituido por PNG)"
fi

if grep -q 'android:roundIcon=' "$MANIFEST"; then
  ok "AndroidManifest ya tiene roundIcon"
else
  if grep -q 'android:icon=' "$MANIFEST"; then
    if command -v python3 >/dev/null 2>&1; then
      MANIFEST="$MANIFEST" python3 << 'PY'
import os, re, sys
p = os.environ["MANIFEST"]
t = open(p, encoding="utf-8").read()
if "android:roundIcon=" in t:
    sys.exit(0)
t2, n = re.subn(
    r'(android:icon="[^"]*")',
    r'\1\n        android:roundIcon="@mipmap/ic_launcher_round"',
    t,
    count=1,
)
if n != 1:
    sys.exit("No pude insertar android:roundIcon en AndroidManifest.xml")
open(p, "w", encoding="utf-8").write(t2)
PY
    else
      sed -i 's|android:icon="@mipmap/ic_launcher"|android:icon="@mipmap/ic_launcher"\n        android:roundIcon="@mipmap/ic_launcher_round"|' "$MANIFEST"
    fi
    ok "Añadido android:roundIcon al AndroidManifest"
  else
    log "AVISO: no encontré android:icon= en el manifest; añádelo a mano:"
    log '  android:icon="@mipmap/ic_launcher"'
    log '  android:roundIcon="@mipmap/ic_launcher_round"'
  fi
fi

echo
ok "Icono aplicado."
echo
echo "  Icono: circulo azul con mando (sin fondo blanco)"
echo "  Adaptive: mipmap-anydpi-v26 + drawable-nodpi/ic_launcher_foreground.png"
echo
echo "Siguiente paso — reconstruir la app:"
echo "  ./gradlew :app:assembleDebug"
echo
echo "El APK queda en:"
echo "  app/build/outputs/apk/debug/app-debug.apk"
echo
exit 0

